-- Read-only baseline extracted from TESTE on 2026-08-13.
-- Source: Resultado_da_Query (24).xlsx; do not edit as deployment source.
CREATE OR REPLACE PROCEDURE STP_GRAVAFILA_PRA (
p_NUNOTA    IN AD_TGFSEQENT.NUNOTA%TYPE,
p_SEQUENCIA IN AD_TGFSEQENT.SEQUENCIA%TYPE,
p_QTDNEG    IN AD_TGFSEQENT.QTDENT%TYPE,
p_DTINICIO  IN AD_TGFSEQENT.DTPREV%TYPE,
p_CODPROD   IN AD_TGFSEQENT.CODPROD%TYPE,
p_PROVISAO   IN AD_TGFSEQENT.PROVISAO%TYPE
) AS
V_SEQPREV INT;
V_SEQENT  INT;
V_SEQ     INT;

V_OLD_PROVISAO CHAR(1);
PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN

-- BUSCAR O VALOR ATUAL DA PROVISAO
BEGIN
SELECT
PROVISAO , SEQENT
INTO
V_OLD_PROVISAO ,V_SEQENT
FROM AD_TGFSEQENT
WHERE CODPROD = p_CODPROD
AND NUNOTA = p_NUNOTA
AND SEQUENCIA = p_SEQUENCIA;
EXCEPTION WHEN NO_DATA_FOUND THEN
V_OLD_PROVISAO := 'N';
END;

--BUSCA A PROXIMA SEQUENCIA NA FILA
SELECT NVL(MAX(SEQENT),0) + 10
INTO V_SEQPREV
FROM AD_TGFSEQENT E
WHERE E.CODPROD = P_CODPROD;

IF V_OLD_PROVISAO = 'S' AND p_PROVISAO = 'N' THEN
V_SEQ := V_SEQPREV;
ELSE
V_SEQ := V_SEQENT;
END IF;



-- Inserção ou atualização da sequência
MERGE INTO AD_TGFSEQENT QT
USING (SELECT p_NUNOTA AS NUNOTA,
p_SEQUENCIA AS SEQUENCIA,
p_QTDNEG AS QTDNEG,
p_DTINICIO AS DTINICIO,
p_CODPROD AS CODPROD
FROM DUAL) ITE
ON (QT.NUNOTA = ITE.NUNOTA AND QT.SEQUENCIA = ITE.SEQUENCIA)
WHEN MATCHED THEN
UPDATE SET QT.QTDENT = ITE.QTDNEG, QT.DTPREV = p_DTINICIO, QT.PROVISAO = p_PROVISAO, QT.SEQENT = V_SEQ
WHEN NOT MATCHED THEN
INSERT (NUNOTA, SEQUENCIA, SEQENT, QTDENT, DTPREV, DTLANC, CODPROD, PROVISAO)
VALUES (ITE.NUNOTA, ITE.SEQUENCIA, V_SEQPREV, ITE.QTDNEG, ITE.DTINICIO, SYSDATE, ITE.CODPROD,p_PROVISAO);

COMMIT; -- Confirma as alterações
END STP_GRAVAFILA_PRA;
/
